DROP TABLE IF EXISTS temp_update_permission;

CREATE TEMPORARY TABLE temp_update_permission (
id SERIAL PRIMARY KEY,
sub_per text,
channel_permission text,
subscribe_permission text
);

INSERT INTO temp_update_permission(id,sub_per,channel_permission,subscribe_permission)
VALUES

    (#{item.id},#{item.subPermission,typeHandler=com.threeatom.common.mybatis.typehandler.FastJsonArrayTypeHandler},
    #{item.channelPermission,typeHandler=com.threeatom.common.mybatis.typehandler.FastJsonArrayTypeHandler},
    #{item.subscribePermission,typeHandler=com.threeatom.common.mybatis.typehandler.FastJsonArrayTypeHandler})
;

UPDATE gc_user_access_permission uap
SET channel_permission = temp.channel_permission::json,
subscribe_permission = temp.subscribe_permission::json
FROM temp_update_permission temp
WHERE temp.id = uap.id;

SELECT COUNT(*) FROM gc_user_access_permission;

UPDATE gc_user_access_permission p SET sub_permission = ac.subject_json, channel_permission = ac.channel_json, must_subject_json = ac.must_subject_json, may_subject_json = ac.may_subject_json, subscribe_permission = ac.subscribe_json FROM gc_user_access uac LEFT JOIN gc_access ac ON ac.id = uac.access_id WHERE uac.id = p.user_access_id
AND ac.master_id = #{masterId}
AND uac.user_id = #{userId}
